# ---------- короткие помощники ----------
def H2(t, lead=""): return {"t": "h2", "text": t, "lead": lead}
def P(*ps): return {"t": "text", "ps": list(ps)}
def CARDS(items, cols=3, dark=()): return {"t": "cards", "rows": items, "cols": cols, "dark": list(dark)}
def CHECK(*cards): return {"t": "checkcards", "cards": list(cards)}
def STEPS(*items): return {"t": "steps", "rows": list(items)}
def FAQ(*items): return {"t": "faq", "rows": list(items)}
def DOCS(title="Документы", groups=None, rest=False):
    d = {"t": "docs", "title": title}
    if groups:
        d["groups"] = list(groups)  # показать только эти группы (например, документы одной вкладки)
    if rest:
        d["rest"] = True  # показать группы, которые не выведены другими блоками документов на странице
    return d
def PEOPLE(tag, title="", building=None): return {"t": "people", "tag": tag, "title": title, "building": building}
def PHONES(items, cols=2): return {"t": "phones", "rows": items, "cols": cols}
def LINKS(*items): return {"t": "links", "rows": list(items)}
def TABS(*tabs): return {"t": "tabs", "tabs": list(tabs)}
def FEED(rubric=None, limit=3, title="", more=True, empty=""): return {"t": "feed", "rubric": rubric, "limit": limit, "title": title, "more": more, "empty": empty}
def NOTE(t): return {"t": "note", "text": t}
def T(t, **kw): d = {"t": t}; d.update(kw); return d


